param([int]$TargetRps=50,[int]$DurationSeconds=120,[string]$FlagKey='menu_itau_mobile',[string]$PostgresPassword=$env:POSTGRES_PASSWORD)
$ErrorActionPreference='Stop';$root=Split-Path -Parent $PSScriptRoot;$compose=Join-Path $root 'docker-compose.yml';if([string]::IsNullOrWhiteSpace($PostgresPassword)){throw 'Set POSTGRES_PASSWORD to the password of the existing PostgreSQL volume'};$env:POSTGRES_PASSWORD=$PostgresPassword;$base=Join-Path $env:TEMP ('feature-flag-k6-'+[guid]::NewGuid().ToString());$outReport=$base+'.out.log';$errReport=$base+'.err.log'
function Wait-Healthy([int]$timeout=60){$deadline=(Get-Date).AddSeconds($timeout);do{try{$r=Invoke-WebRequest -UseBasicParsing http://localhost:8080/healthz -TimeoutSec 2;if($r.StatusCode -eq 200){return}}catch{};Start-Sleep -Seconds 2}while((Get-Date)-lt $deadline);throw 'application did not become healthy before timeout'}
Write-Host '[1/5] Starting stack';docker compose -f $compose up -d --build postgres nats app;Wait-Healthy
Write-Host '[2/5] Enabling target flag';$headers=@{'Content-Type'='application/json'};Invoke-WebRequest -UseBasicParsing -Method Patch -Uri "http://localhost:8080/v1/flags/$FlagKey" -Headers $headers -Body '{"enabled":true}'|Out-Null
Write-Host "[3/5] Starting k6 at $TargetRps req/s";$script=Join-Path $root 'scripts';$args=@('run','-e',"BASE_URL=http://host.docker.internal:8080",'-e',"FLAG_KEY=$FlagKey",'-e',"TARGET_RPS=$TargetRps",'-e',"DURATION=${DurationSeconds}s",'-e','PREALLOCATED_VUS=100','-e','MAX_VUS=500','-e','GRACEFUL_STOP=5s','/scripts/evaluate-load.js');$k6=Start-Process docker -ArgumentList (@('run','--rm','--add-host=host.docker.internal:host-gateway','-v',"${script}:/scripts:ro",'grafana/k6')+$args) -RedirectStandardOutput $outReport -RedirectStandardError $errReport -PassThru -NoNewWindow
Start-Sleep -Seconds ([Math]::Max(10,[Math]::Floor($DurationSeconds*.25)));Write-Host '[4/5] Chaos: restarting NATS';docker compose -f $compose restart nats;Start-Sleep -Seconds ([Math]::Max(10,[Math]::Floor($DurationSeconds*.25)));Write-Host '[4/5] Chaos: restarting PostgreSQL';docker compose -f $compose restart postgres;Wait-Healthy;Start-Sleep -Seconds ([Math]::Max(10,[Math]::Floor($DurationSeconds*.25)));Write-Host '[4/5] Chaos: recreating application';docker compose -f $compose up -d --no-deps --build app
Write-Host '[5/5] Waiting for k6 report';$deadline=(Get-Date).AddSeconds($DurationSeconds+60);while(-not $k6.HasExited -and (Get-Date)-lt $deadline){Start-Sleep -Seconds 2};if(-not $k6.HasExited){Stop-Process -Id $k6.Id -Force;throw 'k6 runner exceeded timeout while waiting for report'};Get-Content -LiteralPath $outReport;Get-Content -LiteralPath $errReport;Remove-Item -LiteralPath $outReport,$errReport -Force -ErrorAction SilentlyContinue;if($k6.ExitCode -ne 0){throw "k6 chaos test failed with exit code $($k6.ExitCode)"};Write-Host 'Chaos test completed.'